"""Canonical generated bytes and isolated Git checkout regressions (CI discovery)."""
import json
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

from test_packages import gate, GitSnapshotTestCase, source_fixture, wheel_record
from package_generated import validate_generated, validate_record


class CanonicalGeneratedTests(GitSnapshotTestCase):
    def test_generated_bytes_reject_parser_tolerance(self):
        cases = [('crates/plenora-storage-core', name) for name in
                 ('.cargo_vcs_info.json', 'Cargo.toml', 'Cargo.lock')]
        cases += [('cp310-abi3-win_amd64', 'plenora_storage-3.0.3.dist-info/' + name)
                  for name in ('METADATA', 'WHEEL')]
        for context, name in cases:
            good = source_fixture(context, name)
            validate_generated(good, name, context)
            lines = good.splitlines(keepends=True)
            mutations = {
                'unixfrom': b'From 7061796c6f6164\n' + good,
                'duplicate': lines[0] + good,
                'continuation': good.replace(b'\n', b'\n ', 1),
                'crlf': good.replace(b'\n', b'\r\n'),
                'cr': good.replace(b'\n', b'\r'),
                'reordered': lines[1] + lines[0] + b''.join(lines[2:]),
                'trailing-space': good.replace(b'\n', b' \n', 1),
                'bom': b'\xef\xbb\xbf' + good,
            }
            if name == '.cargo_vcs_info.json':
                mutations['compact-json'] = json.dumps(json.loads(good)).encode()
            for variant, bad in mutations.items():
                with self.subTest(name=name, variant=variant), self.assertRaises(ValueError):
                    validate_generated(bad, name, context)

    def test_record_serialization_is_canonical(self):
        name = 'plenora_storage-3.0.3.dist-info/RECORD'
        entries = wheel_record([('a.py', b'a'), ('b.py', b'b'), (name, b'')])
        good = entries[-1][1]
        validate_record(entries, 'cp310-abi3-win_amd64')
        for context in (entries[:-1], entries):
            with self.assertRaisesRegex(ValueError, 'complete wheel context'):
                validate_generated(b'arbitrary', name, 'cp310-abi3-win_amd64', context)
        lines = good.splitlines(keepends=True)
        for bad in (b'From 7061796c6f6164\n' + good, lines[0] + good,
                    good.replace(b'\n', b'\r\n'), good.replace(b'\n', b'\r'),
                    lines[1] + lines[0] + b''.join(lines[2:]),
                    good.replace(b'a.py', b'"a.py"'), good.replace(b'\n', b' \n', 1),
                    good.replace(b'\n', b'\n ', 1), b'\xef\xbb\xbf' + good):
            with self.subTest(bad=bad[:20]), self.assertRaises(ValueError):
                validate_record(entries[:-1] + [(name, bad)], 'cp310-abi3-win_amd64')


class ReleaseCheckoutTests(unittest.TestCase):
    def test_shallow_untrusted_source_and_clone(self):
        (gate.ROOT / 'target').mkdir(exist_ok=True)
        with tempfile.TemporaryDirectory(dir=gate.ROOT / 'target') as temporary:
            base = Path(temporary)
            root = base / 'shallow'
            subprocess.run(env=gate.git_env(), args=gate.git_command('clone', '--no-local', '--depth=1', '--quiet',
                                           gate.ROOT.resolve().as_uri(), str(root)),
                           check=True, capture_output=True)
            empty = base / 'empty.gitconfig'
            empty.write_bytes(b'')
            with patch.dict(os.environ, {'GIT_CONFIG_GLOBAL': str(empty),
                                         'GIT_CONFIG_NOSYSTEM': '1',
                                         'GIT_CONFIG_COUNT': '0',
                                         'GIT_CONFIG_PARAMETERS': '',
                                         'GIT_TEST_ASSUME_DIFFERENT_OWNER': '1'}), \
                    patch.object(gate, 'ROOT', root):
                refused = subprocess.run(['git', 'rev-parse', 'HEAD'], cwd=root,
                                         capture_output=True)
                self.assertNotEqual(refused.returncode, 0)
                self.assertIn(b'dubious ownership', refused.stderr)
                self.assertEqual(subprocess.check_output(
                    gate.git_command('rev-parse', '--is-shallow-repository'), cwd=root).strip(), b'true')
                revision = gate.release_revision()
                with gate.release_checkout() as work:
                    self.assertEqual(subprocess.check_output(
                        gate.git_command('rev-parse', 'HEAD', work=work), cwd=work).decode().strip(), revision)
                    self.assertEqual((work / 'README.md').read_bytes(), (root / 'README.md').read_bytes())
                self.assertEqual(gate.source_bytes('README.md'), subprocess.check_output(
                    gate.git_command('show', 'HEAD:README.md'), cwd=root))
                self.assertIn('readme.md', gate.tracked_paths())

    def test_clone_error_preserves_git_diagnostic(self):
        failed = subprocess.CompletedProcess([], 128, b'', b'fatal: synthetic clone failure\n')
        with patch.object(gate, 'check_git_version'), patch.object(gate.subprocess, 'run', return_value=failed):
            with self.assertRaisesRegex(ValueError, 'cannot create isolated release checkout: fatal: synthetic clone failure'):
                with gate.release_checkout():
                    self.fail('failed clone yielded a checkout')
